from __future__ import annotations

def seo_guides() -> list[dict]:
    return [
        {"slug":"rebar-weight-calculator-guide","title":"Rebar Weight Calculator Guide","category":"Construction Planning","topic":"concrete","parent":"rebar-weight-calculator","description":"Calculate reinforcing bar length and weight using common US bar sizes, metric diameters and a visible project allowance.","answer":"Calculate total bar length from the number of bars and cut length, then multiply by the published unit weight for the selected size. US users commonly identify reinforcing bars by ASTM-style bar number; metric users can enter diameter in millimeters.","steps":[("Choose the bar system","Use a US bar number or metric diameter; do not mix nominal labels and actual diameter assumptions."),("Measure cut length","Include lap, hooks and bends only when the project design requires them."),("Calculate total length","Multiply bar count by cut length and keep each bar direction separate."),("Convert to weight","Multiply total length by the selected unit-weight table and add a project-specific allowance.")],"formula":"total weight = bar count × cut length × unit weight","example":"Ten 20 ft bars with a unit weight of 1.502 lb/ft weigh 300.4 lb before any cutting allowance.","mistakes":"Do not infer structural bar size from a calculator result. Bar spacing, lap length and reinforcement design must come from the project drawings or qualified design.","faqs":[("Are US bar numbers the same as millimeters?","No. US bar numbers and metric diameters are different identification systems."),("Which standard is referenced?","Use current supplier data and applicable ASTM/ACI project requirements; tables can vary by market."),("Is this a structural design tool?","No. It estimates material weight only.") ]},
        {"slug":"steel-weight-calculator-guide","title":"Steel Weight Calculator Guide","category":"Construction Planning","topic":"concrete","parent":"steel-weight-calculator","description":"Estimate steel weight for common shapes such as flat bar, round bar, square tube and angle using dimensions and density.","answer":"Calculate cross-sectional area and length, then multiply by material density. Use the exact section dimensions and steel grade or supplier mass table when available; nominal size alone may not equal actual dimensions.","steps":[("Select the shape","Choose plate, round bar, angle, tube or another section."),("Enter actual dimensions","Use inches or millimeters from the product specification."),("Calculate volume","Area or section volume multiplied by length gives cubic volume."),("Apply density","Use the supplier or grade density and round to the purchase unit.")],"formula":"weight = cross-sectional area × length × material density","example":"A flat bar 2 in wide × 0.25 in thick × 10 ft long has 5 in² of volume per foot before density conversion.","mistakes":"Using nominal tube size as wall thickness, ignoring hollow sections, and treating all stainless or alloy steels as identical density.","faqs":[("Is A36 steel always the same weight?","Dimensions control weight; grade affects properties more than basic density."),("Can I calculate tubing?","Yes, use outside and inside dimensions or the manufacturer's mass table."),("Does this price steel?","No. It estimates mass; supplier pricing and market conditions are separate.") ]},
        {"slug":"earthwork-volume-calculator-guide","title":"Earthwork Volume Calculator Guide","category":"Construction Planning","topic":"landscaping","parent":"earthwork-volume-calculator","description":"Estimate excavation, fill and stockpile volume from length, width, depth and separate sections.","answer":"For simple rectangular earthwork, multiply length by width by average depth. For sloped or irregular excavation, split the area into sections or use average end areas. Keep cut, fill, swell and compaction assumptions separate.","steps":[("Map the work","Separate excavation, imported fill and stockpile areas."),("Measure average depth","Record high and low points when depth changes."),("Calculate in-place volume","Use the designed geometry before applying material behavior."),("Review swell and compaction","Loose haul volume and compacted fill volume are not the same.")],"formula":"rectangular volume = length × width × average depth","example":"A 30 ft × 20 ft excavation with an average depth of 2 ft contains 1,200 ft³, or 44.44 yd³ in place.","mistakes":"Using one maximum depth for the whole site, treating trucked loose soil as compacted fill, and ignoring unsuitable material or disposal.","faqs":[("What is swell?","Excavated soil may occupy more loose volume than it did in place."),("What is shrinkage?","Placed fill may require more loose material to achieve a compacted volume."),("Is this a grading plan?","No. Complex sites need survey and earthwork design.") ]},
        {"slug":"slope-calculator-guide","title":"Slope Calculator Guide: Rise, Run, Grade and Angle","category":"Construction Planning","topic":"landscaping","parent":"slope-calculator","description":"Convert rise and run into slope percentage, ratio and angle for ramps, drainage and terrain planning.","answer":"Slope percentage equals rise divided by horizontal run multiplied by 100. The angle is the arctangent of rise divided by run. Use horizontal run, not the sloped surface length.","steps":[("Measure rise","Use vertical change in inches, feet or millimeters."),("Measure horizontal run","Keep it separate from the diagonal length."),("Calculate grade","Divide rise by run and multiply by 100."),("Convert angle","Use arctan(rise ÷ run) when an angle is needed.")],"formula":"grade(%) = rise ÷ run × 100; angle = arctan(rise ÷ run)","example":"A 6 in rise over 10 ft horizontal run is 0.5 ÷ 10 × 100 = 5% grade.","mistakes":"Using diagonal length as run, confusing a 5% grade with a 5-degree angle, and applying a generic accessibility rule without checking local requirements.","faqs":[("Is percent grade the same as degrees?","No. They describe the same slope in different ways."),("Can this size a ramp?","It can convert dimensions, but ramp design must follow applicable accessibility and safety requirements."),("What about drainage?","Drainage slope depends on surface, flow, soil and local design practice.") ]},
        {"slug":"paver-base-calculator-guide","title":"Paver Base Calculator Guide","category":"Landscaping","topic":"landscaping","parent":"paver-base-calculator","description":"Estimate crushed-stone base, bedding sand and pavers for patios and walkways using separate installed depths.","answer":"Calculate paver area first, then calculate the base and bedding layers separately. Depth must be converted to feet before volume calculation, and the required base depends on soil, drainage, climate and intended load.","steps":[("Measure paver area","Split patios, paths and borders into sections."),("Set base depth","Use project-specific guidance for soil and traffic."),("Calculate each layer","Area × depth gives cubic feet for base and bedding."),("Add pavers and edging","Apply layout waste to pavers and keep edging hardware separate.")],"formula":"layer volume(ft³) = area(ft²) × depth(ft); cubic yards = ft³ ÷ 27","example":"A 240 ft² patio with a 6 in base needs 120 ft³, or 4.44 yd³ of base material before compaction allowance.","mistakes":"Using paver thickness as base depth, ignoring compaction, and assuming decorative walkway specifications apply to vehicle areas.","faqs":[("Does the base need compaction?","Most paver systems require proper compaction; follow the system specifications."),("Is bedding sand the same as base aggregate?","No. They serve different functions and use different depths."),("Can this design a driveway?","It estimates volume only; driveway base design needs site and load guidance.") ]},
        {"slug":"construction-duration-calculator-guide","title":"Construction Duration Calculator Guide","category":"Construction Planning","topic":"flooring","parent":"construction-duration-calculator","description":"Estimate a simple construction duration from quantity, daily production rate, workdays and contingency.","answer":"Divide project quantity by realistic daily production, round up to workdays and add separate allowances for mobilization, curing, inspections, weather and material delays.","steps":[("Define the quantity","Use the same unit as the production rate."),("Choose production rate","Base it on crew size, access, preparation and actual conditions."),("Calculate workdays","Quantity ÷ daily production, rounded up."),("Add non-production time","Include setup, curing, inspections, weather and delivery risk.")],"formula":"workdays = ceil(total quantity ÷ daily production); calendar days = workdays + allowances","example":"Installing 800 ft² at 200 ft² per workday requires 4 production days before setup, delivery and contingency.","mistakes":"Treating production rate as guaranteed, ignoring cure time, and adding weather days into the production rate and then adding them again.","faqs":[("Is this a contractor schedule?","No. It is a planning estimate."),("Should curing count as workdays?","Curing may be calendar time even when no crew is working; list it separately."),("Does crew size change duration?","Usually, but access and workflow can limit the benefit of adding workers.") ]},
    ]
